// ==UserScript==
// @name         Kéo thả & Phím tắt dòng thuốc - HIS Kiên Giang
// @version      1.1.4
// @description  Di chuyển dòng thuốc bằng kéo thả hoặc Shift + Mũi tên. Tự động hủy chọn/focus và khôi phục giao diện gốc ngay khi click ra vị trí khác.
// @match        https://bvdkkiengiang.vnpthis.vn/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    let currentSelectedId = null;

    const Sortable = (function () {
        function Sortable(el, options) {
            this.el = el;
            this.options = Object.assign({
                animation: 150,
                handle: null,
                draggable: '> *',
                onEnd: null
            }, options);

            this._onTapStart = this._onTapStart.bind(this);
            this._onDragOver = this._onDragOver.bind(this);
            this._onDrop = this._onDrop.bind(this);
            this._onDragEnd = this._onDragEnd.bind(this);

            this._bindEvents();
        }

        Sortable.prototype = {
            _bindEvents: function () {
                this.el.addEventListener('mousedown', this._onTapStart, false);
                this.el.addEventListener('dragover', this._onDragOver, false);
                this.el.addEventListener('drop', this._onDrop, false);
                this.el.addEventListener('dragend', this._onDragEnd, false);
            },

            _onTapStart: function (evt) {
                let target = evt.target;
                if (this.options.handle && !target.closest(this.options.handle)) return;

                const dragEl = target.closest(this.options.draggable);
                if (!dragEl || dragEl.parentElement !== this.el) return;

                this.dragEl = dragEl;
                this.oldIndex = Array.from(this.el.children).indexOf(dragEl);
                dragEl.draggable = true;
            },

            _onDragOver: function (evt) {
                evt.preventDefault();
                evt.dataTransfer.dropEffect = 'move';

                const target = evt.target.closest(this.options.draggable);
                if (target && target !== this.dragEl && target.parentElement === this.el) {
                    const rect = target.getBoundingClientRect();
                    const next = (evt.clientY - rect.top) / (rect.bottom - rect.top) > 0.5;
                    this.el.insertBefore(this.dragEl, next && target.nextSibling || target);
                }
            },

            _onDrop: function (evt) {
                evt.stopPropagation();
            },

            _onDragEnd: function () {
                if (!this.dragEl) return;
                this.dragEl.draggable = false;
                const newIndex = Array.from(this.el.children).indexOf(this.dragEl);

                if (typeof this.options.onEnd === 'function' && this.oldIndex !== newIndex) {
                    this.options.onEnd({
                        item: this.dragEl,
                        oldIndex: this.oldIndex,
                        newIndex: newIndex
                    });
                }
                this.dragEl = null;
            }
        };

        return Sortable;
    })();

    function resolveSystemFunctions() {
        const contexts = [window];
        try { if (window.parent && window.parent !== window) contexts.push(window.parent); } catch (e) {}
        try { if (window.top && window.top !== window) contexts.push(window.top); } catch (e) {}

        for (let i = 0; i < window.frames.length; i++) {
            try { contexts.push(window.frames[i]); } catch (e) {}
        }

        for (const ctx of contexts) {
            try {
                if (typeof ctx.len_bhyt === 'function' && typeof ctx.xuong_bhyt === 'function') {
                    return {
                        moveUp: ctx.len_bhyt.bind(ctx),
                        moveDown: ctx.xuong_bhyt.bind(ctx),
                        type: 'FUNCTION'
                    };
                }
            } catch (e) {}
        }

        return { type: 'DOM_FALLBACK' };
    }

    function triggerRowMoveButton(rowElement, direction) {
        if (!rowElement) return false;

        const selector = direction === 'UP'
            ? '[onclick*="len_bhyt"], [title*="Lên"], .fa-arrow-up, .fa-chevron-up, .ui-icon-arrow-1-n'
            : '[onclick*="xuong_bhyt"], [title*="Xuống"], .fa-arrow-down, .fa-chevron-down, .ui-icon-arrow-1-s';

        const btn = rowElement.querySelector(selector);
        if (btn) {
            btn.click();
            return true;
        }
        return false;
    }

    async function executeMove(rowId, direction) {
        const sysHandler = resolveSystemFunctions();
        const currentRowEl = document.getElementById(String(rowId));

        if (sysHandler.type === 'FUNCTION') {
            if (direction === 'UP') {
                sysHandler.moveUp(String(rowId), 'list_thuoc_kgg');
            } else {
                sysHandler.moveDown(String(rowId), 'list_thuoc_kgg');
            }
            return true;
        } else {
            return triggerRowMoveButton(currentRowEl, direction);
        }
    }

    function getAllRows() {
        return Array.from(document.querySelectorAll('#list_thuoc_kgg tbody tr.jqgrow'));
    }

    function applySelectionHighlight() {
        const allRows = getAllRows();

        allRows.forEach(row => {
            if (currentSelectedId !== null && String(row.id) === String(currentSelectedId)) {
                row.classList.add('ui-state-highlight');
                row.setAttribute('aria-selected', 'true');
            } else {
                row.classList.remove('ui-state-highlight');
                row.setAttribute('aria-selected', 'false');
            }
        });

        try {
            const $grid = window.$ ? window.$('#list_thuoc_kgg') : null;
            if ($grid) {
                if (currentSelectedId !== null && typeof $grid.setSelection === 'function') {
                    $grid.setSelection(String(currentSelectedId), false);
                } else if (currentSelectedId === null && typeof $grid.resetSelection === 'function') {
                    $grid.resetSelection();
                }
            }
        } catch (e) {}
    }

    function setSelectedId(id) {
        if (id !== null && !isNaN(parseInt(id, 10))) {
            currentSelectedId = parseInt(id, 10);
        } else {
            currentSelectedId = null;
        }
        applySelectionHighlight();
    }

    function initDragAndDrop() {
        const tableBody = document.querySelector('#list_thuoc_kgg tbody');
        if (!tableBody || tableBody.dataset.dragInitialized) return;

        new Sortable(tableBody, {
            animation: 150,
            handle: '.jqgrow',
            draggable: '.jqgrow',
            onEnd: async function (evt) {
                const oldIdx = evt.oldIndex;
                const newIdx = evt.newIndex;
                const diff = oldIdx - newIdx;

                if (diff === 0) return;

                let activeId = parseInt(evt.item.id, 10);
                const steps = Math.abs(diff);
                const isGoingUp = diff > 0;

                for (let i = 0; i < steps; i++) {
                    const success = await executeMove(activeId, isGoingUp ? 'UP' : 'DOWN');
                    if (!success && i === 0) {
                        alert("Không thể thực hiện di chuyển dòng thuốc.");
                        return;
                    }

                    activeId = isGoingUp ? activeId - 1 : activeId + 1;
                    setSelectedId(activeId);

                    await new Promise(resolve => setTimeout(resolve, 150));
                }
            }
        });

        tableBody.dataset.dragInitialized = "true";
        tableBody.style.cursor = "grab";
    }

    document.addEventListener('click', function (e) {
        const clickedRow = e.target.closest('#list_thuoc_kgg tbody tr.jqgrow');
        if (clickedRow) {
            setSelectedId(clickedRow.id);
        } else {
            if (currentSelectedId !== null) {
                setSelectedId(null);
            }
        }
    }, true);

    let isMovingKey = false;
    window.addEventListener('keydown', async function (e) {
        if (!e.shiftKey || (e.key !== 'ArrowUp' && e.key !== 'ArrowDown')) return;

        const activeEl = document.activeElement;
        if (activeEl && ['INPUT', 'TEXTAREA', 'SELECT'].includes(activeEl.tagName)) return;

        if (currentSelectedId === null) return;

        const rows = getAllRows();
        if (rows.length === 0) return;

        const rowIds = rows.map(r => parseInt(r.id, 10)).filter(n => !isNaN(n));
        const minId = Math.min(...rowIds);
        const maxId = Math.max(...rowIds);

        const isGoingUp = e.key === 'ArrowUp';

        if (isGoingUp && currentSelectedId <= minId) return;
        if (!isGoingUp && currentSelectedId >= maxId) return;

        e.preventDefault();

        if (isMovingKey) return;
        isMovingKey = true;

        const currentIdToMove = currentSelectedId;
        const nextSelectedId = isGoingUp ? currentSelectedId - 1 : currentSelectedId + 1;

        await executeMove(currentIdToMove, isGoingUp ? 'UP' : 'DOWN');
        setSelectedId(nextSelectedId);

        setTimeout(() => {
            const nextRowEl = document.getElementById(String(nextSelectedId));
            if (nextRowEl) {
                nextRowEl.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
            }
            isMovingKey = false;
        }, 160);
    }, true);

    const observer = new MutationObserver(() => {
        if (document.getElementById('list_thuoc_kgg')) {
            initDragAndDrop();
            if (currentSelectedId !== null) {
                applySelectionHighlight();
            }
        }
    });

    observer.observe(document.body, { childList: true, subtree: true });

    if (document.getElementById('list_thuoc_kgg')) {
        initDragAndDrop();
    }
})();

// ==UserScript==
// @name         HIS - Nút In Tên A4
// @version      1.0.0
// @match        *://*/*
// @grant        GM_addStyle
// @grant        GM_log
// @run-at       document-idle
// ==/UserScript==

(function() {
  'use strict';

  GM_addStyle(`
    .btn-his-a4 {
      margin-left: 6px;
      padding: 2px 8px;
      background-color: #1a73e8;
      color: #ffffff;
      font-weight: bold;
      font-size: 12px;
      border: 1px solid #1557b0;
      border-radius: 4px;
      cursor: pointer;
      vertical-align: middle;
      line-height: 18px;
      display: inline-block;
      transition: background-color 0.15s ease;
    }
    .btn-his-a4:hover {
      background-color: #1557b0;
    }
  `);

  function openA4Print(hoten, tuoi) {
    let ageStr = (tuoi || '').trim().toUpperCase();
    if (ageStr) {
      ageStr = ageStr.replace(/tuổi/gi, 'T').trim();
      if (!ageStr.endsWith('T')) ageStr += ' T';
    }

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Trình duyệt đang chặn cửa sổ Popup in. Vui lòng cấp quyền cho phép mở pop-up.');
      return;
    }

    const printHtml = `
      <!DOCTYPE html>
      <html lang="vi">
      <head>
        <meta charset="UTF-8">
        <title>TENA4 - In A4</title>
        <style>
          @page {
            size: A4 portrait;
            margin: 4cm;
          }
          * { box-sizing: border-box; margin: 0; padding: 0; }
          html, body {
            width: 100%;
            height: 100%;
            background: #fff;
            font-family: 'Times New Roman', Times, serif;
            overflow: hidden;
          }
          .print-container {
            width: 130mm;
            height: 217mm;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            margin: 0 auto;
            font-weight: bold;
            text-transform: uppercase;
            overflow: hidden;
            word-break: keep-all !important;
            overflow-wrap: normal !important;
            word-wrap: normal !important;
            hyphens: none !important;
          }
          #p-name {
            line-height: 1.15;
            width: 100%;
            word-break: keep-all !important;
            white-space: normal;
          }
          #p-age {
            line-height: 1.15;
            width: 100%;
            margin-top: 15px;
            word-break: keep-all !important;
            white-space: normal;
          }
          @media print {
            body { margin: 0 !important; padding: 0 !important; }
            .print-container { width: 100% !important; height: 100% !important; }
          }
        </style>
      </head>
      <body>
        <div class="print-container" id="container">
          <div id="p-name"></div>
          <div id="p-age"></div>
        </div>
        <script>
          const name = ${JSON.stringify(hoten)};
          const age = ${JSON.stringify(ageStr)};

          const container = document.getElementById('container');
          const nameEl = document.getElementById('p-name');
          const ageEl = document.getElementById('p-age');

          nameEl.innerHTML = name.split(/\\s+/).map(w => '<span class="word" style="display:inline-block; white-space:nowrap;">' + w + '</span>').join(' ');
          ageEl.innerHTML = age.split(/\\s+/).map(w => '<span class="word" style="display:inline-block; white-space:nowrap;">' + w + '</span>').join(' ');

          function autoFitText() {
            let low = 12;
            let high = 220;
            let bestSize = low;
            const maxW = container.clientWidth;
            const maxH = container.clientHeight;

            while (low <= high) {
              let mid = Math.floor((low + high) / 2);
              nameEl.style.fontSize = mid + 'pt';
              ageEl.style.fontSize = Math.max(8, mid - 4) + 'pt';

              let wordOverflow = false;
              const words = container.querySelectorAll('.word');
              for (let i = 0; i < words.length; i++) {
                if (words[i].offsetWidth > maxW) {
                  wordOverflow = true;
                  break;
                }
              }

              const isOverflow = wordOverflow || container.scrollHeight > maxH || container.scrollWidth > maxW;
              if (!isOverflow) {
                bestSize = mid;
                low = mid + 1;
              } else {
                high = mid - 1;
              }
            }

            nameEl.style.fontSize = bestSize + 'pt';
            ageEl.style.fontSize = Math.max(8, bestSize - 4) + 'pt';
          }

          document.fonts.ready.then(() => {
            autoFitText();
            setTimeout(() => {
              window.print();
            }, 250);
          });
        <\/script>
      </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(printHtml);
    printWindow.document.close();
  }

  function injectA4Button() {
    if (document.getElementById('btn-his-a4')) return;

    const hotenInput = document.getElementById('hoten');
    if (!hotenInput) return;

    const btn = document.createElement('button');
    btn.id = 'btn-his-a4';
    btn.type = 'button';
    btn.className = 'btn-his-a4';
    btn.innerText = 'A4';
    btn.title = 'In bảng tên A4';

    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const getVal = (id) => {
        const el = document.getElementById(id);
        if (!el) return '';
        return (el.value || el.innerText || el.textContent || '').trim();
      };

      const hoten = getVal('hoten').toUpperCase();
      const tuoi = getVal('tuoi').toUpperCase();
      openA4Print(hoten, tuoi);
    });

    hotenInput.insertAdjacentElement('afterend', btn);
    GM_log('Đã gắn nút A4 vào giao diện HIS');
  }

  injectA4Button();
  const observer = new MutationObserver(() => injectA4Button());
  observer.observe(document.body, { childList: true, subtree: true });
})();
